import{_ as a,o,c as i,a2 as d}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Capítulo 106 | Refinamiento del Reino · Reino de la Percepción Originaria · Comparación del Bando Depredador vs el Bando Simbiótico","description":"","frontmatter":{"title":"Capítulo 106 | Refinamiento del Reino · Reino de la Percepción Originaria · Comparación del Bando Depredador vs el Bando Simbiótico","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","路线对比"],"related":["04-掠夺式修炼体系批判","01-衡元宙核心世界观","14-修炼境界统一划分"]},"headers":[],"relativePath":"es/0106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"es/0106_模块1-感元境-掠夺派vs共生派对比.md"}'),r={name:"es/0106_模块1-感元境-掠夺派vs共生派对比.md"};function s(l,e,n,t,c,u){return o(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="capitulo-106-reino-de-la-percepcion-originaria-comparacion-de-sistema-entre-el-bando-depredador-y-el-bando-simbiotico" tabindex="-1">Capítulo 106 | Reino de la Percepción Originaria: comparación de sistema entre el bando depredador y el bando simbiótico <a class="header-anchor" href="#capitulo-106-reino-de-la-percepcion-originaria-comparacion-de-sistema-entre-el-bando-depredador-y-el-bando-simbiotico" aria-label="Permalink to &quot;Capítulo 106 | Reino de la Percepción Originaria: comparación de sistema entre el bando depredador y el bando simbiótico&quot;">​</a></h1><blockquote><p>Módulo: Módulo uno · Refinamiento profundo de los reinos | Documentos base: 04, 01, 14</p></blockquote><h2 id="introduccion-dos-logicas-de-cultivo-dos-clases-de-universo" tabindex="-1">Introducción: dos lógicas de cultivo, dos clases de universo <a class="header-anchor" href="#introduccion-dos-logicas-de-cultivo-dos-clases-de-universo" aria-label="Permalink to &quot;Introducción: dos lógicas de cultivo, dos clases de universo&quot;">​</a></h2><p>El Reino de la Percepción Originaria no es solo el punto de partida del cultivo, sino también la primera encrucijada de la cosmovisión: desde la primera absorción de energía, el cultivador ya está parado en la bifurcación — o «tomo del mundo», o «crezco con el mundo». Estas dos frases suenan cercanas, pero conducen a dos universos por completo distintos: uno es un coto de caza donde el fuerte come al débil; el otro es una comunidad de vida donde todos los seres ascienden juntos.</p><p>Este artículo da la comparación a nivel de sistema entre el Sistema de Cultivo Depredador y la Civilización Simbiótica del Ancla.</p><p>Los Seis Axiomas Supremos son la propia línea divisoria: el Axioma del Antidepredación separa «tomar» de «crecer»; el Axioma de la República de las Diez Mil Razas separa «solo mi raza» de «todas las razas»; el Axioma de la Ascensión Dimensional Colectiva separa «asciendo solo» de «ascendemos juntos»; el Axioma de la Autodisciplina Causal separa «deuda en otro lugar» de «yo cargo mi propio fruto»; el Axioma de la Prioridad de la Ley separa «reglas a mi conveniencia» de «ley estable y autoconsistente». La Ley de Igualdad Infinita Universal para todos los Seres establece que todo ser porta en sí mismo el Poder Infinito Fundamental: los tranquilos conservan un infinito básico garantizado y no serán eliminados por los tiempos, mientras que los esforzados y los jóvenes supremos pueden apilar niveles superiores de infinito. El origen infinito lo porta todo ser —la lógica depredadora de «solo los fuertes pueden sobrevivir» ya es inválida de su faz.</p><h2 id="i-tabla-maestra-de-la-comparacion-de-sistema" tabindex="-1">I. Tabla maestra de la comparación de sistema <a class="header-anchor" href="#i-tabla-maestra-de-la-comparacion-de-sistema" aria-label="Permalink to &quot;I. Tabla maestra de la comparación de sistema&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimensión</th><th>Bando depredador</th><th>Bando simbiótico (Ancla)</th></tr></thead><tbody><tr><td>Fuente de energía</td><td>Devora el origen ajeno</td><td>Toma del ciclo del mundo, retroalimenta</td></tr><tr><td>Actitud hacia los débiles</td><td>Selección natural, muere si débil</td><td>Barandilla para todos, ni uno menos</td></tr><tr><td>Lógica del techo</td><td>Un cima sobre un cementerio</td><td>El todo asciende junto</td></tr><tr><td>Horizonte temporal</td><td>Drena ahora, desecha después</td><td>Doble circulación, sostenible</td></tr><tr><td>Actitud hacia el riesgo</td><td>El riesgo es un filtro</td><td>El riesgo es un problema a gestionar</td></tr><tr><td>Línea ética</td><td>La fuerza hace el derecho</td><td>Autodisciplina causal</td></tr><tr><td>Destino último</td><td>El señor de un solo sector estelar</td><td>Reino del Ancla Equilibrada Hiperpluralista</td></tr></tbody></table><h2 id="ii-las-tres-falacias-del-bando-depredador" tabindex="-1">II. Las tres falacias del bando depredador <a class="header-anchor" href="#ii-las-tres-falacias-del-bando-depredador" aria-label="Permalink to &quot;II. Las tres falacias del bando depredador&quot;">​</a></h2><ol><li>Falacia de suma cero: cree que el poder es fijo, así que para ganarlo hay que quitar a otro —ciego al hecho de que la energía del ciclo del mundo es renovable y expansiva.</li><li>Falacia de la eliminación natural: cree que los débiles merecen ser eliminados —ciego al hecho de que el infinito básico de los tranquilos deja a los lentos seguir sin ser aplastados.</li><li>Falacia del «depredador ilustrado»: cree que un depredador bondadoso es el mejor depredador —ciego al hecho de que la estructura misma de la depredación es la enfermedad, no el temple del depredador.</li></ol><h2 id="iii-el-«depredador-ilustrado»-y-la-regresion-historica" tabindex="-1">III. El «depredador ilustrado» y la regresión histórica <a class="header-anchor" href="#iii-el-«depredador-ilustrado»-y-la-regresion-historica" aria-label="Permalink to &quot;III. El «depredador ilustrado» y la regresión histórica&quot;">​</a></h2><p>El llamado depredador ilustrado —es decir, el fuerte que no mata sin razón, que «comparte algo» con los débiles, que se llama a sí mismo benevolente— es el autoengaño más peligroso del bando depredador. Un cazador amable sigue siendo un cazador; su bondad es solo el refinamiento de su gestión de la presa. La historia muestra una y otra vez que la era «ilustrada» de un sistema depredador es siempre la víspera de la regresión: una vez agotados los cotos de caza, los fuertes «benevolentes» son los primeros en volverse contra los propios.</p><h2 id="iv-el-picaro-justo-un-aviso-a-los-«elegidos»" tabindex="-1">IV. El pícaro justo: un aviso a los «elegidos» <a class="header-anchor" href="#iv-el-picaro-justo-un-aviso-a-los-«elegidos»" aria-label="Permalink to &quot;IV. El pícaro justo: un aviso a los «elegidos»&quot;">​</a></h2><p>El bando simbiótico no pretende que su propio bando sea perfecto. La variante más insidiosa es el «pícaro justo»: quien usa el manto de la justicia para seguir saqueando, que dice «hago esto por la simbiosis» mientras drena a otros para su propio avance.</p><p>Tómese a Lin Hao, el protagonista de este universo, como piedra de toque: su camino no es volverse el más fuerte de un coto de caza, sino demostrar que el fuerte puede ascender dejando aún a los débiles un camino de vuelta. Cada vez que es tentado a decir «soy especial, así que las reglas no me aplican a mí», ese es el preciso instante en que el Demonio Interior del Atajo llama —esta es la línea interior que todo cultivador del bando simbiótico debe sostener.</p><h2 id="v-cinco-puntos-de-aterrizaje-esenciales" tabindex="-1">V. Cinco puntos de aterrizaje esenciales <a class="header-anchor" href="#v-cinco-puntos-de-aterrizaje-esenciales" aria-label="Permalink to &quot;V. Cinco puntos de aterrizaje esenciales&quot;">​</a></h2><ul><li>Antidesperdicio de nivel energético: el «fuerte come débil» del bando depredador desperdicia más potencial evolutivo que cualquier guerra; la doble circulación del bando simbiótico es la verdadera alta eficiencia.</li><li>Antidepredación: cada fila de la tabla maestra es una línea roja que el bando simbiótico no cruzará.</li><li>Comparación con el techo de Tang Luo: el techo del bando depredador es un señor sobre un cementerio; el techo del bando simbiótico levanta el cosmos entero.</li><li>Cobertura total de las Diez Mil Razas: la tabla maestra cubre toda dimensión, desde la fuente de energía hasta el destino último, sin punto ciego.</li><li>Apertura total hiperpluralista: la comparación misma es evidencia abierta —el bando depredador no se atreve a publicarla, porque cada dimensión expone su propia pequeñez.</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Una tabla no necesita retórica; las dos columnas ya hablan. En el Reino de la Percepción Originaria, la primera absorción que el cultivador elige decide en qué columna estará de pie el resto de su vida —por eso esta comparación se coloca al principio mismo de toda la biblioteca: que todo lector vea, antes de elegir el camino, en qué universo está a punto de entrar.</p><h2 id="enlaces" tabindex="-1">Enlaces <a class="header-anchor" href="#enlaces" aria-label="Permalink to &quot;Enlaces&quot;">​</a></h2><ul><li>Documentos relacionados: <a href="./04-掠夺式修炼体系批判.html">04-Crítica del Sistema de Cultivo Depredador</a> · <a href="./01-衡元宙核心世界观.html">01-Cosmovisión núcleo de Heng Yuan Zhou</a> · <a href="./14-修炼境界统一划分.html">14-Clasificación unificada de reinos de cultivo</a></li></ul>',21)])])}const b=a(r,[["render",s]]);export{m as __pageData,b as default};
